CREATE TABLE IF NOT EXISTS n8n_chat_historico_mensagens (
  id SERIAL PRIMARY KEY,
  session_id VARCHAR(255) NOT NULL,
  message JSONB NOT NULL,
  created_at TIMESTAMP DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_session_id ON n8n_chat_historico_mensagens(session_id);
